import json, html
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
c=json.loads((ROOT/'site.config.json').read_text())
e=html.escape
v=c['ventures']
def link(label,url,cls='text-link'): return f'<a class="{cls}" href="{url}">{label} <span aria-hidden="true">↗</span></a>'
def cards():
 return '<div class="venture-grid">'+''.join(f'<article class="venture-card" style="--venture:{x["color"]}"><a class="brand-panel" href="/ventures/{x["slug"]}" aria-label="Explore {e(x["name"])}"><img src="{x["logo"]}" alt="{e(x["name"])}" width="320" height="130" loading="lazy"></a><div class="card-copy"><p class="eyebrow">{x["category"]}</p><h3>{x["name"]}</h3><p>{x["description"]}</p><div class="card-links">{link("Explore venture","/ventures/"+x["slug"])}{link("Visit website",x["url"])}</div></div></article>' for x in v)+'</div>'
def intro(kicker,title,desc): return f'<section class="page-intro wrap"><p class="eyebrow">{kicker}</p><h1>{title}</h1><p class="lead">{desc}</p></section>'
def philosophy(): return '<div class="principles">'+''.join(f'<article><span class="number">0{i+1}</span><h3>{a}</h3><p>{b}</p></article>' for i,(a,b) in enumerate([('Development','Our ventures grew from experience with association operations, local reporting needs, and the difficulty of finding election information.'),('Operations','Each venture has its own website, services, and audience. Corporate inquiries are handled through GovernUp.'),('Independence','The Gazette maintains editorial independence. VotePG provides nonpartisan information. Neither serves as a promotional channel for our other businesses.')]))+'</div>'
founder='Blake Hemphill is an entrepreneur and organizational leader with experience in executive operations, community governance, technology development, and publishing. As Founder & Chief Executive Officer of GovernUp Solutions, LLC, he develops ventures that improve access to information, strengthen community institutions, and solve operational problems.'
news='<article class="news-row"><time datetime="2026-09-11">September 11, 2026</time><div><p class="eyebrow">Venture launch</p><h3>The Westphalia Gazette begins publication</h3><p>The launch established an independent local publication focused on Westphalia. It marks the addition of journalism to GovernUp’s portfolio.</p>'+link('Read the venture profile','/ventures/westphalia-gazette')+'</div></article>'
pages={
'index':('Home',c['description'],f'''<section class="hero"><div class="wrap hero-grid"><div><h1>GovernUp Solutions</h1><p class="lead">GovernUp Solutions develops and operates ventures in local journalism, community association software, professional services, and civic information.</p><div class="actions">{link('Explore Our Ventures','/ventures','button')}{link('About GovernUp','/about','button outline')}</div></div><aside class="portfolio-index"><p class="eyebrow">Our ventures</p>{''.join(f'<a href="/ventures/{x["slug"]}"><span>0{i+1}</span><div>{x["name"]}<small>{x["category"]}</small></div><b aria-hidden="true">↗</b></a>' for i,x in enumerate(v))}</aside></div></section>

<section class="portfolio section" id="ecosystem"><div class="wrap"><div class="section-heading"><h2>Our Ventures</h2><p>The Westphalia Gazette leads our current growth focus. Each venture serves a distinct audience and maintains its own identity.</p></div>{cards()}</div></section>
<section class="wrap section founder" id="about"><div><p class="eyebrow">Founder & Chief Executive Officer</p><h2>Blake<br>Hemphill</h2></div><div><p>{founder}</p>{link('Meet our founder','/leadership')}</div></section>
<section class="philosophy section"><div class="wrap"><h2>How we operate</h2>{philosophy()}</div></section>
<section class="wrap section"><div class="section-heading"><h2>News & Updates</h2></div>{news}{link('All corporate updates','/news')}</section>'''),
'about':('About','The background and operations of GovernUp Solutions, LLC.',intro('About GovernUp','About GovernUp Solutions','GovernUp Solutions develops, operates, and supports ventures addressing practical needs in communities and institutions.')+f'<section class="wrap prose section"><h2>Our evolution</h2><p>Our beginnings in community governance and technology grew from firsthand experience with association operations. That work led to Covenant and Covenant Management Partners: distinct approaches to tools, services, and governance support.</p><p>The same habit of noticing unmet needs led to independent local journalism through The Westphalia Gazette and accessible civic information through VotePG. Together, these ventures give GovernUp a broader purpose across media, technology, professional services, and information.</p><p>Our ventures are at different stages of development. Common ownership does not mean identical operations, staffing, or maturity, and our ventures are not presented as separate legal subsidiaries.</p><h2>Editorial and civic independence</h2><p>The Gazette’s editorial decisions remain independent of commercial and personal interests. VotePG maintains a nonpartisan civic purpose. These responsibilities remain distinct from the company’s software and professional services.</p>{link("Ownership & independence","/disclosures")}</section>'),
'ventures':('Our Ventures','Explore our portfolio of media, technology, professional services, and civic information.',intro('Our ventures','Our Ventures','Explore the four publicly available ventures in the GovernUp portfolio. Each has its own audience, offerings, and website.')+f'<section class="wrap section">{cards()}</section>'),
'leadership':('Leadership','Meet Blake Hemphill, Founder & Chief Executive Officer.',intro('Leadership','Blake Hemphill','Founder & Chief Executive Officer · GovernUp Solutions, LLC')+f'<section class="wrap prose section"><h2>Background</h2><p>{founder}</p><p>Blake is Founder & Publisher of The Westphalia Gazette and the founder behind Covenant, Covenant Management Partners, and VotePG. His work connects an interest in useful technology and accessible information with a practical understanding of organizational leadership.</p><p>Experience serving as an HOA board president helped inspire the association software and services ventures. The Gazette and VotePG respond to different needs: sustained local reporting and easier access to civic information.</p><p>His ambition is to build enduring businesses that strengthen community institutions, with clear boundaries between corporate ownership, independent journalism, and nonpartisan civic information.</p><p class="note">Professional and community roles are biographical context. They do not imply government or homeowners association sponsorship, endorsement, or a client relationship.</p>{link("Contact GovernUp","/contact")}</section>'),
'news':('News & Updates','Company announcements and venture milestones.',intro('News & Updates','News & Updates','Corporate announcements and verified venture milestones. Gazette reporting remains on the publication’s own website.')+f'<section class="wrap section">{news}</section>'),
'contact':('Contact','Contact GovernUp Solutions about business, partnerships, and corporate matters.',intro('Contact','Contact GovernUp','For general business inquiries, partnerships, and corporate matters.')+f'''<section class="wrap section contact-grid"><div><h2>Corporate inquiries</h2><p>{link(c['email'],'mailto:'+c['email'])}</p><h3>Looking for a specific venture?</h3><p>For product demonstrations, association services, news tips, or election-platform questions, contact the relevant venture directly.</p><ul class="venture-links">{''.join('<li>'+link(x['name'],x['url'])+'</li>' for x in v)}</ul></div><form id="gu-contact-form"><label for="name">Name</label><input id="name" name="name" autocomplete="name" maxlength="120" required><label for="email">Email</label><input id="email" name="email" type="email" autocomplete="email" maxlength="254" required><label for="interest">Inquiry category</label><select id="interest" name="interest" required><option value="">Select a category</option><option>General business inquiry</option><option>Partnerships</option><option>Corporate matters</option></select><label for="message">Message</label><textarea id="message" name="message" rows="6" maxlength="5000" required></textarea><p class="note">We use these details to respond to your inquiry. Please avoid sensitive personal information. Read our <a href="/privacy">privacy notice</a>.</p><button class="button" type="submit">Send inquiry <span aria-hidden="true">↗</span></button><p id="form-status" role="status" aria-live="polite"></p></form></section>'''),
'privacy':('Privacy','How corporate contact inquiries are handled.',intro('Privacy notice','Privacy Notice','This notice covers the GovernUp Solutions corporate contact form.')+f'<section class="wrap prose section"><h2>Information you provide</h2><p>The form collects your name, email address, inquiry category, and message so we can review and respond to your request. Please do not send financial account details, identification documents, or other sensitive personal information.</p><h2>Delivery and processing</h2><p>Contact inquiries are delivered to our corporate inbox using Resend, our email delivery provider. The website is hosted on Vercel. Service providers may process technical request information needed to operate and secure these services.</p><h2>Questions and requests</h2><p>Contact <a href="mailto:{c["email"]}">{c["email"]}</a> with questions or requests about information submitted through this form. Each venture maintains its own website and applicable privacy information.</p></section>'),
'disclosures':('Ownership & Independence','Corporate ownership, editorial independence, and nonpartisan civic information.',intro('Corporate disclosures','Ownership & Independence',c['legalName']+' is the current legal company behind this portfolio.')+f'<section class="wrap prose section"><h2>Our portfolio</h2><p>{c["legalDisclosure"]}</p>'+''.join(f'<h2>{x["name"]}</h2><p>{x["disclosure"]}</p>' for x in v)+'</section>')}
for x in v:
 pages['ventures/'+x['slug']]=(x['name'],x['description'],intro(x['category'],x['name'],x['description'])+f'<section class="wrap section detail-grid"><div class="detail-brand"><img src="{x["logo"]}" alt="{e(x["name"])}" width="400" height="200">{link("Visit official website",x["url"],"button")}</div><div><h2>Overview</h2><p class="lead">{x["detail"]}</p><ul class="offerings">'+''.join(f'<li>{z}</li>' for z in x['offerings'])+f'</ul><div class="note disclosure">{x["disclosure"]}</div>{link("Back to all ventures","/ventures")}</div></section>')
cssvars=';'.join('--'+k+':'+z for k,z in c['colors'].items())
for path,(title,desc,body) in pages.items():
 url=c['url']+('/' if path=='index' else '/'+path)
 nav=''.join(f'<a href="{u}"'+(' aria-current="page"' if u==('/' if path=='index' else '/'+path) else '')+f'>{n}</a>' for n,u in c['navigation'])
 schema={'@context':'https://schema.org','@type':'Organization','name':c['name'],'legalName':c['legalName'],'url':c['url'],'logo':c['url']+c['logo'],'founder':{'@type':'Person','name':'Blake Hemphill'}}
 out=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{e(title)} | {c['name']}</title><meta name="description" content="{e(desc,quote=True)}"><link rel="canonical" href="{url}"><meta property="og:title" content="{e(title,quote=True)} | {c['name']}"><meta property="og:description" content="{e(desc,quote=True)}"><meta property="og:url" content="{url}"><meta property="og:type" content="website"><link rel="icon" href="/favicon-32x32.png"><link rel="stylesheet" href="/assets/site.css"><style>:root{{{cssvars}}}</style><script type="application/ld+json">{json.dumps(schema)}</script><script src="/assets/site.js" defer></script></head><body><a class="skip-link" href="#main">Skip to content</a><header><div class="wrap header-inner"><a class="wordmark" href="/"><img src="{c['logo']}" alt="" width="42" height="42"><span>{c['name']}</span></a><button class="menu-toggle" aria-controls="navigation" aria-expanded="false">Menu</button><nav id="navigation" aria-label="Primary">{nav}</nav></div></header><main id="main">{body}</main><footer><div class="wrap"><div class="footer-top"><div><a class="footer-name" href="/">{c['name']}</a></div><div class="footer-links">{''.join(link(x['name'],x['url']) for x in v)}</div></div><div class="footer-bottom"><p>© 2026 {c['legalName']}</p><a href="/privacy">Privacy</a><a href="/disclosures">Ownership & Independence</a><a href="/contact">Contact</a></div><p class="fineprint">{c['legalDisclosure']}</p></div></footer></body></html>'''
 dest=ROOT/(path+'.html'); dest.parent.mkdir(parents=True,exist_ok=True);dest.write_text(out)
(ROOT/'sitemap.xml').write_text('<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">'+''.join('<url><loc>'+c['url']+('/' if p=='index' else '/'+p)+'</loc></url>' for p in pages)+'</urlset>')
(ROOT/'robots.txt').write_text('User-agent: *\nAllow: /\nSitemap: '+c['url']+'/sitemap.xml\n')
print('Generated',len(pages),'pages')
